/* ---- v26: El Niño ---- */
addX([
  ["El Niño: drought and heat", "El Niño: hulaw ug kainit"],
  ["A very strong El Niño can bring months of less rain and hotter days. Prepare water, shade and food before the dry months get worse. See also: Guides, El Niño: drought, water and heat.", "Ang kusog kaayo nga El Niño mahimong magdala og pipila ka bulan nga gamay ang ulan ug mas init ang adlaw. Andama ang tubig, landong ug pagkaon sa dili pa mograbe ang uga nga mga bulan. Basaha usab: Giya, El Niño: hulaw, tubig ug kainit."],
  ["Extra stored drinking water, aiming for 14 days for everyone", "Dugang nga gitipigan nga inom nga tubig, tumong og 14 ka adlaw para sa tanan"],
  ["Use clean containers with tight lids. Replace the water every 6 months.", "Gamita ang limpyong sudlanan nga hugot ang takup. Ilisi ang tubig matag 6 ka bulan."],
  ["Tight lids or covers on every water container, to keep mosquitoes out", "Hugot nga takup sa matag sudlanan sa tubig, aron dili makasulod ang lamok"],
  ["Scrub any open container once a week.", "Kuskusa kausa sa usa ka semana ang bisan unsang abli nga sudlanan."],
  ["Know where to get water near you: wells, springs, water points and refilling stations, and a way to carry it", "Hibaloi kung asa makakuha og tubig duol kanimo: atabay, bukal, water point ug refilling station, ug paagi sa pagdala niini"],
  ["Oral rehydration salts and a thermometer", "Oral rehydration salts ug termometro"],
  ["Hydrite, digital thermometer", "Hydrite, digital nga termometro"],
  ["Buckets or drums to catch rainwater whenever it rains", "Timba o drum para masalo ang tubig-ulan kung moulan"],
  ["Boil or treat rainwater before you drink it.", "Lata o hugasi ang tubig-ulan sa dili pa imnon."],
  ["Hats, light cotton clothes and an umbrella for shade", "Kupya, nipis nga bisting koton ug payong para sa landong"],
  ["A battery fan or hand fan, a power bank and a flashlight for brownouts", "Bentilador nga baterya o pahangin nga kamot, power bank ug flashlight para sa brownout"],
  ["Dry-season garden: mulch (dry leaves or straw), a watering can and seeds of crops that take dry weather (camote, cassava, okra)", "Tanaman sa uga nga panahon: tabon sa yuta (uga nga dahon o dagami), banyera sa pagpanubig ug liso sa tanum nga kaya ang uga (camote, kamoteng kahoy, okra)"],
  ["Water early in the morning at the roots. See Grow vegetables outside in Guides.", "Tubigi sa sayong buntag sa gamut. Tan-awa ang Pagtanom og utanon sa gawas sa Giya."],
  ["Clear dry grass and trash from around the house, and keep a bucket of water ready", "Limpyohi ang uga nga sagbot ug basura libot sa balay, ug andama ang timba nga tubig"],
  ["Extra staple food: rice, canned fish, dried fish, noodles", "Dugang nga basehang pagkaon: bugas, de-lata nga isda, uga nga isda, pansit"],
  ["Prices can rise in a drought. Buy a little more each week, not everything at once.", "Mahimong motaas ang presyo sa hulaw. Palita og gamay nga dugang kada semana, dili tanan sa usa ka higayon."],
  ["El Niño is active now", "Aktibo karon ang El Niño"],
  ["PAGASA says a very strong El Niño is active and may last into mid-2027. Expect less rain and hotter days. Parts of Leyte have been listed for dry conditions.", "Gisulti sa PAGASA nga aktibo ang kusog kaayo nga El Niño ug mahimong molungtad hangtod tunga sa 2027. Gamay ang ulan ug mas init ang adlaw. Ang pipila ka bahin sa Leyte nalista nga uga."],
  ["From PAGASA, checked 13 Nov 2026. PAGASA updates its advisory every month.", "Gikan sa PAGASA, gisusi 13 Nob 2026. Mag-update ang PAGASA sa advisory matag bulan."],
  ["What to do about El Niño", "Unsay buhaton batok sa El Niño"], ["Hide", "Tagoa"]
]);

